/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The workspace is then kept,
 * inert, for `DELETED_WORKSPACE_RETENTION_DAYS` so its owner can restore it.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  assertNotArchived("Organization", input.orgId, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const deleted = await orgRepo.archiveOrg(input.orgId);
  await emit("organization.deleted", {
    ...actorEnvelope(actor),
    slug: deleted.slug,
  });

  return deleted;
}

/**
 * Brings a deleted workspace back while its retention window is open. A deleted
 * workspace resolves to no `Actor` (sign-in and membership lookups skip it), so
 * the caller is identified by user id and checked here. Once the window has
 * closed the workspace is gone, whether or not the sweep has purged it yet.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (org === null || isWindowClosed(org, new Date())) {
    throw new NotFoundError("Organization", orgId);
  }

  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (!isArchived(org)) return org;

  const restored = await orgRepo.restoreOrg(orgId);
  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

/** A deleted workspace whose retention window has run out. Live ones never close. */
function isWindowClosed(org: Organization, now: Date): boolean {
  return (
    org.archivedAt !== null &&
    org.archivedAt <= retentionCutoff(now, DELETED_WORKSPACE_RETENTION_DAYS)
  );
}

