describe("deleting a workspace", () => {
  it("publishes organization.deleted and keeps every row it owns", async () => {
    const tenant = await newTenant("delete");
    const deleted = capture("organization.deleted");

    const result = await deleteWorkspace(tenant);

    expect(result.archivedAt).not.toBeNull();
    expect(deleted).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        slug: tenant.org.slug,
      }),
    ]);
    expect(await orgRepo.findOrgById(tenant.org.id)).not.toBeNull();
    expect(rowCount("members", tenant.org.id)).toBe(4);
  });

  it("records organization.deleted in the audit log against the workspace", async () => {
    const tenant = await newTenant("audit-delete");
    await deleteWorkspace(tenant);

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.deleted"],
      limit: 25,
      cursor: null,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.deleted",
      actorId: tenant.userIds.owner,
      subjectKind: "organization",
      subjectId: tenant.org.id,
    });
  });

  it("refuses to delete a workspace that is already deleted", async () => {
    const tenant = await newTenant("delete-twice");
    await deleteWorkspace(tenant);

    await expect(deleteWorkspace(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("while deleted, a workspace is inert", () => {
  it("is not listed for its members and cannot be signed into", async () => {
    const tenant = await newTenant("hidden");
    await deleteWorkspace(tenant);

    const listed = await organizationService.listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.map((org) => org.id)).not.toContain(tenant.org.id);
    expect(await organizationService.resolveOrgBySlug(tenant.org.slug)).toBeNull();

    const principal: SessionPrincipal = {
      userId: tenant.userIds.owner,
      email: "owner@example.test",
      activeOrgId: tenant.org.id,
      expiresAt: toIsoTimestamp(new Date(T0.getTime() + DAY_MS)),
    };
    expect(await resolveActorForOrg(principal, tenant.org.slug)).toBeNull();
  });

  it("keeps its slug reserved until the purge", async () => {
    const tenant = await newTenant("reserved");
    await deleteWorkspace(tenant);

    const created = await organizationService.createOrganization(tenant.userIds.admin, {
      name: "Newcomer",
      slug: tenant.org.slug,
      plan: "free",
    });

    expect(created.slug).not.toBe(tenant.org.slug);
  });

  it("creates no notifications for it", async () => {
    const tenant = await newTenant("quiet");
    await deleteWorkspace(tenant);

    const rows = await notificationService.notify(
      tenant.org.id,
      "member_joined",
      [tenant.userIds.admin],
      {
        title: "A new member joined",
        body: "Someone joined",
        href: "/settings/members",
        actorId: tenant.userIds.owner,
      },
    );

    expect(rows).toEqual([]);
    expect(rowCount("notifications", tenant.org.id)).toBe(0);
  });

  it("keeps a pending invitation pending and refuses to accept it", async () => {
    const tenant = await newTenant("invite");
    const token = randomToken(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "later@example.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );
    await deleteWorkspace(tenant);

    await expect(
      invitationService.acceptInvitation(tenant.userIds.admin, { token }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((invite) => invite.email)).toEqual(["later@example.test"]);
    expect(pending[0]?.acceptedAt).toBeNull();
  });
});

describe("restoring a workspace", () => {
  it("brings the workspace back and publishes organization.restored with the caller as actor", async () => {
    const tenant = await newTenant("restore");
    await deleteWorkspace(tenant);
    const restored = capture("organization.restored");

    advance(DAY_MS);
    const org = await organizationService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );

    expect(org.archivedAt).toBeNull();
    expect(restored).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        slug: tenant.org.slug,
      }),
    ]);

    const listed = await organizationService.listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.map((row) => row.id)).toContain(tenant.org.id);
  });

  it("records organization.restored in the audit log", async () => {
    const tenant = await newTenant("audit-restore");
    await deleteWorkspace(tenant);
    advance(DAY_MS);
    await organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id);

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.restored"],
      limit: 25,
      cursor: null,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      actorId: tenant.userIds.owner,
      subjectKind: "organization",
      subjectId: tenant.org.id,
    });
  });

  it("refuses a member who is not an owner", async () => {
    const tenant = await newTenant("restore-admin");
    await deleteWorkspace(tenant);
    advance(DAY_MS);

    await expect(
      organizationService.restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect((await orgRepo.findOrgById(tenant.org.id))?.archivedAt).not.toBeNull();
  });

  it("answers NotFoundError for a stranger and for a workspace that never existed", async () => {
    const tenant = await newTenant("restore-stranger");
    const stranger = await newTenant("restore-elsewhere");
    await deleteWorkspace(tenant);

    await expect(
      organizationService.restoreOrganization(stranger.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      organizationService.restoreOrganization(
        tenant.userIds.owner,
        "01HZZZZZZZZZZZZZZZZZZZZZZZ" as OrgId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await newTenant("restore-live");
    const restored = capture("organization.restored");

    const org = await organizationService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );

    expect(org).toEqual(tenant.org);
    expect(restored).toHaveLength(0);
  });

  it("is still open on the last instant before the window closes", async () => {
    const tenant = await newTenant("restore-edge-open");
    await deleteWorkspace(tenant);
    advance(WINDOW_MS - 1);

    const org = await organizationService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );
    expect(org.archivedAt).toBeNull();
  });

  it("is closed once the window has run out, before any sweep has purged it", async () => {
    const tenant = await newTenant("restore-edge-closed");
    await deleteWorkspace(tenant);
    advance(WINDOW_MS);

    await expect(
      organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await orgRepo.findOrgById(tenant.org.id)).not.toBeNull();
  });
});

describe("the retention sweep", () => {
  it("leaves a workspace alone while its restore window is open", async () => {
    const tenant = await newTenant("sweep-open");
    await seedWorkspace(tenant);
    await deleteWorkspace(tenant);

    const now = advance(WINDOW_MS - 1);
    await runCleanupArchivedJob(now);

    expect(await orgRepo.findOrgById(tenant.org.id)).not.toBeNull();
    for (const table of SEEDED_TABLES) {
      expect(rowCount(table, tenant.org.id), table).toBeGreaterThan(0);
    }
  });

  it("purges every row the workspace owns once the window has closed, and nothing else", async () => {
    const doomed = await newTenant("sweep-doomed");
    const live = await newTenant("sweep-live");
    const sessionId = await seedWorkspace(doomed);
    await seedWorkspace(live);
    await deleteWorkspace(doomed);

    const now = advance(WINDOW_MS);
    await runCleanupArchivedJob(now);

    expect(orgScopedTables()).toEqual(expect.arrayContaining(SEEDED_TABLES));
    for (const table of orgScopedTables()) {
      expect(rowCount(table, doomed.org.id), table).toBe(0);
    }
    expect(await orgRepo.findOrgById(doomed.org.id)).toBeNull();

    for (const table of SEEDED_TABLES) {
      expect(rowCount(table, live.org.id), table).toBeGreaterThan(0);
    }
    expect(await orgRepo.findOrgById(live.org.id)).not.toBeNull();

    expect(sessionRow(sessionId)?.activeOrgId).toBeNull();
    expect(await userRepo.findUserById(doomed.userIds.owner)).not.toBeNull();
  });

  it("makes a purged workspace unknown, so it can be restored no longer and its name is free", async () => {
    const tenant = await newTenant("sweep-name");
    await deleteWorkspace(tenant);

    const now = advance(WINDOW_MS + DAY_MS);
    await runCleanupArchivedJob(now);

    await expect(
      organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reused = await organizationService.createOrganization(tenant.userIds.admin, {
      name: "Reborn",
      slug: tenant.org.slug,
      plan: "free",
    });
    expect(reused.slug).toBe(tenant.org.slug);
    expect(reused.id).not.toBe(tenant.org.id);
  });
});

