/**
 * Deleting, restoring and purging a workspace.
 *
 * A deleted workspace is kept inert for `DELETED_WORKSPACE_RETENTION_DAYS`:
 * its owner can restore it until the window closes, and the retention sweep
 * then removes every row it owns. The clock is frozen per test so each window
 * boundary is exact.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq, getTableColumns, getTableName, is } from "drizzle-orm";
import { SQLiteTable } from "drizzle-orm/sqlite-core";
import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { newId } from "@/lib/id";
import { hashToken, randomToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import {
  activityEvents,
  attachments,
  comments,
  getDb,
  invitations,
  invoices,
  issueLabels,
  issues,
  labels,
  projectMembers,
  rateLimitBuckets,
  sessions,
} from "@/server/db";
import * as schema from "@/server/db/schema";
import { runCleanupArchivedJob } from "@/server/jobs";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import { record, registerActivityListeners, listActivity } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { resolveActorForOrg } from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * DAY_MS;
const T0 = new Date("2026-03-01T12:00:00.000Z");

/** Every table the purge must leave empty for one workspace. */
const SEEDED_TABLES = [
  "members",
  "invitations",
  "projects",
  "project_members",
  "issues",
  "labels",
  "issue_labels",
  "attachments",
  "comments",
  "notifications",
  "notification_preferences",
  "activity_events",
  "subscriptions",
  "invoices",
  "webhook_endpoints",
  "webhook_deliveries",
  "rate_limit_buckets",
  "search_index",
  "organization_usage",
];

let cleanup: () => void;
let detachActivity: Unsubscribe;
let tenantCount = 0;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

beforeEach(() => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(T0);
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

/** A fresh workspace per test, so one test's deletion never leaks into another. */
async function newTenant(label: string): Promise<Tenant> {
  tenantCount += 1;
  return createTenant(`${label}-${tenantCount}`);
}

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function deleteWorkspace(tenant: Tenant) {
  return organizationService.deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

/** Moves the clock to `offsetMs` after the deletion instant. */
function advance(offsetMs: number): Date {
  const now = new Date(T0.getTime() + offsetMs);
  vi.setSystemTime(now);
  return now;
}

function rowCount(table: string, orgId: OrgId): number {
  const row = getDb()
    .$client.prepare(`SELECT COUNT(*) AS n FROM "${table}" WHERE org_id = ?`)
    .get(orgId) as { n: number };
  return row.n;
}

/** Every table in the schema that carries an `org_id` column. */
function orgScopedTables(): string[] {
  return Object.values(schema)
    .filter(
      (value): value is SQLiteTable =>
        is(value, SQLiteTable) && "orgId" in getTableColumns(value),
    )
    .map((table) => getTableName(table));
}

/** One row in each org-scoped table, written the way production writes them. */
async function seedWorkspace(tenant: Tenant): Promise<string> {
  const db = getDb();
  const orgId = tenant.org.id;
  const ownerId = tenant.userIds.owner;
  const stamp = toIsoTimestamp(new Date());
  const issueId = newId();
  const labelId = newId();

  await usageRepo.recomputeUsage(orgId);

  db.insert(issues)
    .values({
      id: issueId,
      orgId,
      projectId: tenant.project.id,
      number: 1,
      title: "Seeded",
      authorId: ownerId,
    })
    .run();
  db.insert(comments)
    .values({ id: newId(), orgId, issueId, authorId: ownerId, body: "Seeded" })
    .run();
  db.insert(labels).values({ id: labelId, orgId, name: `label-${labelId}` }).run();
  db.insert(issueLabels).values({ orgId, issueId, labelId }).run();
  db.insert(attachments)
    .values({
      id: newId(),
      orgId,
      issueId,
      filename: "seed.txt",
      contentType: "text/plain",
      sizeBytes: 1,
      uploadedBy: ownerId,
    })
    .run();
  db.insert(projectMembers)
    .values({ orgId, projectId: tenant.project.id, userId: ownerId, addedAt: stamp })
    .onConflictDoNothing()
    .run();
  db.insert(invoices)
    .values({
      id: newId(),
      orgId,
      number: `INV-${issueId}`,
      amountCents: 900,
      periodStart: stamp,
      periodEnd: stamp,
    })
    .run();
  db.insert(rateLimitBuckets)
    .values({ id: newId(), orgId, bucketKey: "member:invite", tokens: 5, refilledAt: stamp })
    .run();

  await notificationRepo.insertNotification(orgId, {
    orgId,
    recipientId: ownerId,
    kind: "comment_created",
    title: "Seeded",
    body: "Seeded",
    href: "/issues/1",
    actorId: null,
    channels: ["in_app"],
  });
  await preferenceRepo.upsertPreference({
    orgId,
    userId: ownerId,
    kind: "comment_created",
    inApp: true,
    email: true,
    digestOnly: false,
  });

  const endpoint = await webhookRepo.insertEndpoint(
    { orgId, url: "https://example.test/hook", eventTypes: ["issue.created"] },
    "secret",
  );
  await webhookRepo.enqueueDelivery(orgId, endpoint.id, "issue.created", "{}");

  await searchRepo.upsertSearchDocument(orgId, "project", tenant.project.id, "Seeded", tenant.project.id);
  await invitationRepo.insertInvitation(
    orgId,
    { orgId, email: `invitee-${issueId}@example.test`, role: "member", expiresInDays: 14 },
    ownerId,
    hashToken(randomToken(32)),
  );
  await record(orgId, "project.updated", {
    actorId: ownerId,
    subjectKind: "project",
    subjectId: tenant.project.id,
    projectId: tenant.project.id,
    summary: "Seeded",
  });

  const sessionId = newId();
  db.insert(sessions)
    .values({
      id: sessionId,
      userId: ownerId,
      activeOrgId: orgId,
      tokenHash: hashToken(randomToken(32)),
      expiresAt: toIsoTimestamp(new Date(T0.getTime() + 365 * DAY_MS)),
    })
    .run();

  return sessionId;
}

function sessionRow(sessionId: string) {
  return getDb().select().from(sessions).where(eq(sessions.id, sessionId)).get();
}

