    const now = advance(WINDOW_MS - 1);
    await runCleanupArchivedJob(now);

    expect(await orgRepo.findOrgById(tenant.org.id)).not.toBeNull();
    for (const table of SEEDED_TABLES) {
      expect(rowCount(table, tenant.org.id), table).toBeGreaterThan(0);
    }
  });

  it("purges every row the workspace owns once the window has closed, and nothing else", async () => {
    const doomed = await newTenant("sweep-doomed");
    const live = await newTenant("sweep-live");
    const sessionId = await seedWorkspace(doomed);
    await seedWorkspace(live);
    await deleteWorkspace(doomed);

    const now = advance(WINDOW_MS);
    await runCleanupArchivedJob(now);

    expect(orgScopedTables()).toEqual(expect.arrayContaining(SEEDED_TABLES));
    for (const table of orgScopedTables()) {
      expect(rowCount(table, doomed.org.id), table).toBe(0);
    }
    expect(await orgRepo.findOrgById(doomed.org.id)).toBeNull();

    for (const table of SEEDED_TABLES) {
      expect(rowCount(table, live.org.id), table).toBeGreaterThan(0);
    }
    expect(await orgRepo.findOrgById(live.org.id)).not.toBeNull();

    expect(sessionRow(sessionId)?.activeOrgId).toBeNull();
    expect(await userRepo.findUserById(doomed.userIds.owner)).not.toBeNull();
  });

  it("makes a purged workspace unknown, so it can be restored no longer and its name is free", async () => {
    const tenant = await newTenant("sweep-name");
    await deleteWorkspace(tenant);

    const now = advance(WINDOW_MS + DAY_MS);
    await runCleanupArchivedJob(now);

    await expect(
      organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reused = await organizationService.createOrganization(tenant.userIds.admin, {
      name: "Reborn",
      slug: tenant.org.slug,
      plan: "free",
    });
    expect(reused.slug).toBe(tenant.org.slug);
    expect(reused.id).not.toBe(tenant.org.id);
  });
});

