import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import * as issueService from "@/server/services/issue-service";
import * as organizationService from "@/server/services/organization-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

const DAY_MS = 24 * 60 * 60 * 1000;
const NOW = new Date("2026-06-01T07:00:00.000Z");
const PAST = "2026-01-01T00:00:00.000Z";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

function deleteWorkspace(tenant: Tenant) {
  return organizationService.deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

describe("workspace retention: background jobs", () => {
  it("emits no overdue alert for a deleted workspace", async () => {
    const live = await createTenant("jobs-overdue-live");
    const gone = await createTenant("jobs-overdue-gone");
    await usageRepo.recomputeUsage(live.org.id);
    await usageRepo.recomputeUsage(gone.org.id);

    const liveIssue = await issueService.createIssue(
      live.actors.member,
      issueInput(live.org.id, live.project.id, {
        title: "Late",
        assigneeId: live.userIds.member,
        dueAt: PAST,
      }),
    );
    const goneIssue = await issueService.createIssue(
      gone.actors.member,
      issueInput(gone.org.id, gone.project.id, {
        title: "Late too",
        assigneeId: gone.userIds.member,
        dueAt: PAST,
      }),
    );
    await deleteWorkspace(gone);

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).toContain(liveIssue.id);
    expect(seen).not.toContain(goneIssue.id);
  });

