    const live = await createTenant("jobs-usage-live");
    const gone = await createTenant("jobs-usage-gone");
    await usageRepo.incrementUsage(live.org.id, { issuesUsed: 7 });
    await usageRepo.incrementUsage(gone.org.id, { issuesUsed: 7 });
    await deleteWorkspace(gone);

    expect(await usageRepo.listOrgIdsForRollup(100)).toContain(live.org.id);
    expect(await usageRepo.listOrgIdsForRollup(100)).not.toContain(gone.org.id);

    await runUsageRollupJob(NOW);

    expect((await usageRepo.getUsage(live.org.id)).issuesUsed).toBe(0);
    expect((await usageRepo.getUsage(gone.org.id)).issuesUsed).toBe(7);
  });

