    const live = await createTenant("jobs-trial-live");
    const gone = await createTenant("jobs-trial-gone");
    await deleteWorkspace(gone);

    await runTrialExpiryJob(new Date(Date.now() + 15 * DAY_MS));

    expect((await subscriptionRepo.findSubscription(live.org.id))?.plan).toBe("free");

    const kept = await subscriptionRepo.findSubscription(gone.org.id);
    expect(kept?.plan).toBe("growth");
    expect(kept?.status).toBe("trialing");
  });

  it("marks a deleted workspace's pending webhook deliveries failed, and still delivers a live one's", async () => {
    const live = await createTenant("jobs-hook-live");
    const gone = await createTenant("jobs-hook-gone");

    const liveEndpoint = await webhookRepo.insertEndpoint(
      { orgId: live.org.id, url: "https://example.test/live", eventTypes: ["issue.created"] },
      "secret",
    );
    const goneEndpoint = await webhookRepo.insertEndpoint(
      { orgId: gone.org.id, url: "https://example.test/gone", eventTypes: ["issue.created"] },
      "secret",
    );
    const liveDelivery = await webhookRepo.enqueueDelivery(
      live.org.id,
      liveEndpoint.id,
      "issue.created",
      "{}",
    );
    const goneDelivery = await webhookRepo.enqueueDelivery(
      gone.org.id,
      goneEndpoint.id,
      "issue.created",
      "{}",
    );
    await deleteWorkspace(gone);

    await runWebhookDeliveryJob(NOW);

    const db = getDb();
    const failed = db
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.id, goneDelivery.id))
      .get();
    expect(failed?.status).toBe("failed");
    expect(failed?.deliveredAt).toBeNull();
    expect(failed?.lastError).toBe("workspace is deleted");

    const delivered = db
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.id, liveDelivery.id))
      .get();
    expect(delivered?.status).toBe("delivered");
  });

  it("reindexes a live workspace and skips a deleted one", async () => {
    const live = await createTenant("jobs-reindex-live");
    const gone = await createTenant("jobs-reindex-gone");
    await deleteWorkspace(gone);

    const liveResult = await runSearchReindexJob(live.org.id);
    const goneResult = await runSearchReindexJob(gone.org.id);

    expect(liveResult.processed).toBeGreaterThan(0);
    expect(goneResult.processed).toBe(0);
    expect(await searchRepo.countIndexed(gone.org.id)).toBe(0);
    expect(await orgRepo.findOrgById(gone.org.id)).not.toBeNull();
  });
});

